// --- SLIDE 4: COST SIMULATOR ---
const SlideCost = () => {
  const [headcount, setHeadcount] = useState(200);
  const [salary, setSalary] = useState(8); // Juta
  
  // Logic: 
  // Ambiguity: 15% time wasted (IDC)
  // Switching: 20% efficiency loss (APA)
  // Turnover: 15% risk * 50% annual salary replacement cost (SHRM)
  const totalPayroll = headcount * salary * 1000000 * 12;
  const wasteAmbiguity = totalPayroll * 0.15;
  const wasteSwitching = totalPayroll * 0.20;
  const wasteTurnover = (headcount * 0.15) * (salary * 1000000 * 12 * 0.5);
  const totalWaste = wasteAmbiguity + wasteSwitching + wasteTurnover;

  return (
    <div className="grid lg:grid-cols-12 gap-8 items-center min-h-full slide-enter">
      <div className="lg:col-span-5 space-y-8">
        <SectionHeader title="The Financial Bleed" subtitle="Contextual dissonance isn't just annoying—it's expensive. Based on IDC & APA research." icon={Calculator} color="red"/>
        <div className="glass-card p-6 rounded-2xl space-y-6 border-l-4 border-red-500">
           <div>
             <div className="flex justify-between text-sm font-bold text-slate-600 mb-2">Gen Z Headcount: <span className="text-[#0095DA]">{headcount}</span></div>
             <input type="range" min="50" max="1000" step="10" value={headcount} onChange={(e)=>setHeadcount(Number(e.target.value))} />
           </div>
           <div>
             <div className="flex justify-between text-sm font-bold text-slate-600 mb-2">Avg Salary (Juta/Mo): <span className="text-[#0095DA]">{salary}</span></div>
             <input type="range" min="5" max="25" step="1" value={salary} onChange={(e)=>setSalary(Number(e.target.value))} />
           </div>
           <div className="pt-4 border-t border-slate-200">
             <div className="text-xs text-slate-400 uppercase font-bold tracking-wider mb-1">Total Annual Payroll</div>
             <div className="text-xl font-bold text-slate-700">{formatIDR(totalPayroll).slice(0,-9)} M IDR</div>
           </div>
        </div>
      </div>
      <div className="lg:col-span-7">
        <div className="glass-dark p-10 rounded-3xl text-center shadow-2xl border border-white/10 relative overflow-hidden">
           <div className="relative z-10">
             <h3 className="text-slate-400 font-bold uppercase tracking-widest text-sm mb-4">Estimated Annual Loss</h3>
             <div className="text-6xl font-black text-white mb-2 drop-shadow-xl">{formatIDR(totalWaste).slice(0,-9)}<span className="text-2xl text-slate-500"> M IDR</span></div>
             <p className="text-red-400 text-sm font-medium mb-8">({((totalWaste/totalPayroll)*100).toFixed(1)}% of Payroll)</p>
             
             <div className="grid grid-cols-3 gap-4 text-left">
                <div className="bg-white/10 p-4 rounded-xl border border-white/5">
                   <div className="text-xs text-amber-400 font-bold mb-1">Ambiguity</div>
                   <div className="text-lg font-bold text-white">{formatIDR(wasteAmbiguity).slice(0,-9)} M</div>
                   <div className="text-[9px] text-slate-400 mt-1">15% Time Wasted</div>
                </div>
                <div className="bg-white/10 p-4 rounded-xl border border-white/5">
                   <div className="text-xs text-red-400 font-bold mb-1">Switching</div>
                   <div className="text-lg font-bold text-white">{formatIDR(wasteSwitching).slice(0,-9)} M</div>
                   <div className="text-[9px] text-slate-400 mt-1">20% Prod Loss</div>
                </div>
                <div className="bg-white/10 p-4 rounded-xl border border-white/5">
                   <div className="text-xs text-purple-400 font-bold mb-1">Turnover Risk</div>
                   <div className="text-lg font-bold text-white">{formatIDR(wasteTurnover).slice(0,-9)} M</div>
                   <div className="text-[9px] text-slate-400 mt-1">Replacement Cost</div>
                </div>
             </div>
           </div>
        </div>
      </div>
    </div>
  );
};

