// --- SLIDE 13: ROI SIMULATOR ---
const SlideROI = () => {
  const [efficiency, setEfficiency] = useState(10); // %
  const [turnoverRed, setTurnoverRed] = useState(10); // %
  
  // Base numbers (Hidden assumptions)
  const headcount = 500;
  const avgSalary = 8; // Mn
  const totalPayroll = headcount * avgSalary * 1000000 * 12;
  const programCost = 500000000; // 500Mn IDR Investment

  // Calculations
  const savingsEfficiency = totalPayroll * (efficiency / 100);
  const savingsTurnover = (headcount * (turnoverRed/100)) * (avgSalary * 1000000 * 3); // 3mo salary hiring cost
  const totalBenefit = savingsEfficiency + savingsTurnover;
  const roi = ((totalBenefit - programCost) / programCost) * 100;
  const payback = (programCost / (totalBenefit / 12));

  // Chart Data for Break Even
  const data = [
    { name: 'Month 0', Cost: -programCost/1000000, Value: 0 },
    { name: 'Month 3', Cost: -programCost/1000000, Value: (totalBenefit/4)/1000000 },
    { name: 'Month 6', Cost: -programCost/1000000, Value: (totalBenefit/2)/1000000 },
    { name: 'Month 12', Cost: -programCost/1000000, Value: totalBenefit/1000000 },
  ];

  return (
    <div className="flex flex-col min-h-full justify-center slide-enter">
      <SectionHeader title="Impact & ROI Methodology" subtitle="Phillips ROI Methodology (Level 5 Evaluation) - Measuring the Money." icon={TrendingUp} color="green"/>
      <div className="grid lg:grid-cols-12 gap-8 h-auto lg:h-[450px]">
         {/* Left: Interactive ROI Calculator */}
         <div className="lg:col-span-4 glass-card p-8 rounded-3xl border-l-8 border-green-500 flex flex-col justify-center space-y-8">
            <h3 className="font-bold text-slate-800 mb-2 flex items-center gap-2"><Calculator size={20}/> ROI Simulator</h3>
            
            <div>
               <div className="flex justify-between text-sm font-bold text-slate-600 mb-2">Efficiency Gain: <span className="text-green-600">{efficiency}%</span></div>
               <input type="range" min="5" max="25" step="1" value={efficiency} onChange={(e)=>setEfficiency(Number(e.target.value))} />
               <p className="text-[10px] text-slate-400 mt-1">Productivity improvements (Case 2).</p>
            </div>

            <div>
               <div className="flex justify-between text-sm font-bold text-slate-600 mb-2">Turnover Reduction: <span className="text-green-600">{turnoverRed}%</span></div>
               <input type="range" min="5" max="20" step="1" value={turnoverRed} onChange={(e)=>setTurnoverRed(Number(e.target.value))} />
               <p className="text-[10px] text-slate-400 mt-1">Increased retention (Case 4).</p>
            </div>

            <div className="pt-6 border-t border-slate-200">
               <div className="flex justify-between items-end">
                  <div className="text-xs text-slate-500 uppercase font-bold">Net Benefit (Year 1)</div>
                  <div className="text-2xl font-black text-slate-800">{formatIDR(totalBenefit - programCost).slice(0,-9)} M</div>
               </div>
            </div>
         </div>

         {/* Right: Output Visualization */}
         <div className="lg:col-span-8 bg-slate-900 rounded-3xl p-8 flex flex-col text-white shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 p-10 opacity-5"><Landmark size={200}/></div>
            
            <div className="grid grid-cols-2 gap-8 mb-8 relative z-10">
               <div>
                  <div className="text-sm text-slate-400 uppercase tracking-widest mb-2">Projected ROI</div>
                  <div className="text-6xl font-black text-green-400 drop-shadow-lg">{roi.toFixed(0)}%</div>
               </div>
               <div>
                  <div className="text-sm text-slate-400 uppercase tracking-widest mb-2">Payback Period</div>
                  <div className="text-6xl font-black text-blue-400 drop-shadow-lg">{payback.toFixed(1)} <span className="text-lg">Mo</span></div>
               </div>
            </div>

            <div className="flex-1 w-full h-[200px] lg:h-full relative z-10">
               <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={data}>
                     <defs>
                        <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                           <stop offset="5%" stopColor="#10b981" stopOpacity={0.8}/>
                           <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                        </linearGradient>
                     </defs>
                     <XAxis dataKey="name" stroke="#94a3b8" fontSize={10}/>
                     <YAxis stroke="#94a3b8" fontSize={10}/>
                     <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false}/>
                     <Tooltip contentStyle={{backgroundColor: '#0f172a', border: 'none', borderRadius: '8px'}}/>
                     <ReferenceLine y={0} stroke="white"/>
                     <Area type="monotone" dataKey="Value" stroke="#10b981" fillOpacity={1} fill="url(#colorValue)" />
                     <Line type="monotone" dataKey="Cost" stroke="#ef4444" strokeWidth={2} strokeDasharray="5 5"/>
                  </AreaChart>
               </ResponsiveContainer>
            </div>
         </div>
      </div>
    </div>
  );
};

